/* ==UserStyle==
@name           Google Sites
@namespace      github.com/seenukarthi/Stylus
@version        1.0.0
@description    This Style Sheet for most of the Google website.
@author         Karthikeyan Vaithilingam
==/UserStyle== */

.gb_ee,
    .gb_9d,
    .oz3cqf,
    .std,
    .g,
    a,
    body,
    input,
    button,
    .e9EfHf,
    .tNxQIb,
    .p4wthm,
    .cyspcb,
    .vqseUe,
    .TO .nU > .n0,
    .TO.NQ .nU > .n0,
    .TO.nZ .nU > .n0,
    .ah9 > .CJ,
    .n3 > .CL > .CK,
    .z0 > .L3,
    .Wt5Tfe > *,
    #rso > *,
    .zA > .a4W,
    .apW,
    .yW,
    .H0,
    .aAv,
    .Oa,
    .Tm .ya,
    .apb .aiD,
    .md,
    .aeU .ma,
    .bp .ma,
    .l6,
    .MBeuO,
    .NUnG9d,
    .result-stats,
    .gb_8a:not(.gb_ad),
    .gb_zd,
    .ssJ7i,
    .wHYlTd,
    .e9EfHf,
    .IFnjPb,
    .YmvwI,
    .IFvyDb.hb8SAc,
    textarea.gLFyf,
    .YacQvm.fm06If .ILfuVd,
    .c2xzTb .ILfuVd,
    .Jb0Zif .c2xzTb .ILfuVd,
    .p4wth, .X8u6Oc {
        font-family: var(--vknDefaultFontFamily) !important;
        font-weight: 500 !important;
    }

    .std,
    .g {
        font-size: 12px !important;
    }

    h3 {
        font-size: 18px !important;
    }

    .z0 {
        padding: 0 25% 0 25%;
    }

    .WR .z0 > .L3 {
        border-radius: 9px;
        height: 40px;
        width: 200px;
    }

    .WR .z0 {
        margin: 8px 0 8px 0;
    }

    .z0 {
        padding: 0 5% 0 5%;
    }

    .WR .z0 > .L3 {
        padding: 0 25px 0 2px;
    }

    .google-symbols {
        font-family: "Google Symbols" !important;
    }

    .material-icons-extended {
        font-family: "Material Icons Extended";
    }

.D9SJMe,
    .PIlOad {
        width: 90%;
    }

    body {
        zoom: 100%;
    }

    *:not(.DPvwYc, .google-material-icons) {
        font-family: var(--vknDefaultFontFamily) !important;
    }

    main {
        max-width: initial !important;
        width: calc(100% - 200px) !important;
    }

